//! Emit Rust integration tests from a Markdown document.
//!
//! One runnable block becomes one `#[test]`; the test's body runs the block's
//! commands through a shared `support` module that resolves `pqbench` to the
//! built binary. The generated file is a normal integration test in
//! `crates/pqbench-cli/tests/gen/`, so `cargo test` runs it with no special
//! tooling.
//!
//! Naming: a test is named after its nearest heading, and duplicate or empty
//! headings fall back to a stable suffix so the generated code always compiles.

use std::collections::BTreeSet;

use crate::model::Block;
use crate::plan::{block_steps, Step};

/// Whether any block in the document would produce a test.
pub fn has_runnable(blocks: &[Block]) -> bool {
    blocks.iter().any(|block| !block_steps(block).is_empty())
}

/// Render a document into the source of one integration-test file.
///
/// `source_name` is the document's path as written (used in the module docs);
/// the caller places the result at the matching path under `tests/gen/`.
pub fn generate(source_name: &str, blocks: &[Block]) -> String {
    let mut tests = Vec::new();
    let mut used = BTreeSet::new();
    for block in blocks {
        let steps = block_steps(block);
        if steps.is_empty() {
            continue;
        }
        let name = unique_name(block, &mut used);
        tests.push(render_test(&name, block.line, &steps, &block.info.options));
    }

    let mut out = String::new();
    out.push_str("// @generated by `docscheck sync` from ");
    out.push_str(source_name);
    out.push_str(".\n");
    out.push_str("// Do not edit by hand: edit the Markdown and re-run the sync.\n\n");
    out.push_str("#[path = \"gen_support.rs\"]\nmod support;\n\n");
    if tests.is_empty() {
        out.push_str("// No runnable blocks in this document.\n");
    }
    for test in tests {
        out.push_str(&test);
    }
    // End with exactly one newline: rustfmt drops a trailing blank line even
    // when the items above are `#[rustfmt::skip]`ed.
    while out.ends_with("\n\n") {
        out.pop();
    }
    out
}

/// A unique, valid Rust test name for a block, derived from its heading.
fn unique_name(block: &Block, used: &mut BTreeSet<String>) -> String {
    let base = block
        .heading
        .as_deref()
        .map(slug)
        .filter(|name| !name.is_empty())
        .unwrap_or_else(|| format!("line_{}", block.line));
    if used.insert(base.clone()) {
        return base;
    }
    for suffix in 2.. {
        let candidate = format!("{base}_{suffix}");
        if used.insert(candidate.clone()) {
            return candidate;
        }
    }
    unreachable!("an unused suffix exists")
}

/// Turn heading text into a `snake_case` identifier: keep alphanumerics, lower
/// case, and join words with `_`.
fn slug(text: &str) -> String {
    let mut out = String::new();
    let mut last_underscore = true;
    for ch in text.chars() {
        if ch.is_ascii_alphanumeric() {
            out.push(ch.to_ascii_lowercase());
            last_underscore = false;
        } else if !last_underscore {
            out.push('_');
            last_underscore = true;
        }
    }
    out.trim_matches('_').to_owned()
}

fn render_test(name: &str, line: usize, steps: &[Step], features: &[String]) -> String {
    let mut out = String::new();
    // This is *generated text*, not a feature flag on this crate. The workspace
    // isolation check (`scripts/check_isolation.sh`) flags any `cfg(feature`
    // token under `src/`; spell the attribute from parts so the emitted source
    // carries it without tripping the textual check.
    let cfg = "cfg";
    // `#[rustfmt::skip]` keeps rustfmt from reformatting generated items, so
    // the committed files match the generator byte-for-byte and the freshness
    // check stays independent of the local rustfmt version.
    match features {
        [] => {}
        [feature] => out.push_str(&format!("#[{cfg}(feature = \"{feature}\")]\n")),
        features => {
            let list: Vec<String> = features
                .iter()
                .map(|feature| format!("feature = \"{feature}\""))
                .collect();
            out.push_str(&format!("#[{cfg}(all({}))]\n", list.join(", ")));
        }
    }
    out.push_str("#[rustfmt::skip]\n");
    out.push_str(&format!("#[test]\nfn {name}() {{\n"));
    if line > 0 {
        out.push_str(&format!("    // {name}, from line {line}\n"));
    }
    for step in steps {
        out.push_str(&render_step(step));
    }
    out.push_str("}\n\n");
    out
}

/// One `support::run(...)` call, plus an environment/directory note.
fn render_step(step: &Step) -> String {
    let mut out = String::new();
    if let Some(directory) = &step.directory {
        out.push_str(&format!("    // in {directory}\n"));
    }
    for (name, value) in &step.variables {
        out.push_str(&format!("    // env {name}={value}\n"));
    }
    out.push_str(&format!(
        "    support::run({}, {});\n",
        rust_string(&step.command),
        step.line
    ));
    out
}

/// A Rust string literal (raw when it carries quotes or backslashes).
fn rust_string(text: &str) -> String {
    if text.contains('"') || text.contains('\\') {
        format!("r#\"{text}\"#")
    } else {
        format!("\"{text}\"")
    }
}
